{
  "name": "Todai TV Submission Portal",
  "description": "A stylish, user-friendly video submission portal for University of Tokyo's OCW, featuring Gemini-powered metadata optimization.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SubmissionData {
  // Step 1: Submitter Info
  submitterName: string;
  department: string;
  email: string;

  // Step 2: Content Info
  title: string;
  description: string;
  recordingDate: string;
  category: string;

  // Step 3: Optimization (AI)
  tags: string[];
  aiSummary: string;
  suggestedTitle: string;

  // Step 4: Rights & Files
  copyrightHolder: string;
  releaseScope: 'internal' | 'external' | 'limited';
  fileLink: string;
}

export type Step = 'SUBMITTER' | 'CONTENT' | 'OPTIMIZE' | 'RIGHTS' | 'CONFIRM';

export const STEPS: Step[] = ['SUBMITTER', 'CONTENT', 'OPTIMIZE', 'RIGHTS', 'CONFIRM'];

import { GoogleGenAI, Type } from "@google/genai";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const optimizeMetadata = async (title: string, description: string) => {
  const ai = getAIClient();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Please optimize the following academic video metadata for Todai TV (University of Tokyo's OCW). 
    Original Title: ${title}
    Original Description: ${description}

    Provide:
    1. A more catchy yet academic suggested title.
    2. A concise summary (max 200 words) in professional Japanese.
    3. A list of 5 relevant keywords/tags.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          suggestedTitle: { type: Type.STRING },
          summary: { type: Type.STRING },
          tags: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["suggestedTitle", "summary", "tags"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React from 'react';
import { Step, STEPS } from '../types';

interface StepIndicatorProps {
  currentStep: Step;
}

const STEP_LABELS: Record<Step, string> = {
  SUBMITTER: '申請者情報',
  CONTENT: 'コンテンツ内容',
  OPTIMIZE: 'AI最適化',
  RIGHTS: '権利・ファイル',
  CONFIRM: '確認・送信'
};

export const StepIndicator: React.FC<StepIndicatorProps> = ({ currentStep }) => {
  const currentIndex = STEPS.indexOf(currentStep);

  return (
    <div className="flex items-center justify-between w-full max-w-4xl mx-auto mb-12 px-4">
      {STEPS.map((step, index) => {
        const isActive = index <= currentIndex;
        const isCurrent = step === currentStep;

        return (
          <React.Fragment key={step}>
            <div className="flex flex-col items-center relative group">
              <div 
                className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${
                  isCurrent 
                    ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-110' 
                    : isActive 
                      ? 'bg-blue-100 border-blue-600 text-blue-600' 
                      : 'bg-white border-slate-300 text-slate-400'
                }`}
              >
                {index + 1}
              </div>
              <span className={`absolute -bottom-7 text-[10px] md:text-xs font-medium whitespace-nowrap transition-colors duration-300 ${
                isCurrent ? 'text-blue-600 font-bold' : 'text-slate-500'
              }`}>
                {STEP_LABELS[step]}
              </span>
            </div>
            {index < STEPS.length - 1 && (
              <div className={`flex-1 h-0.5 mx-2 transition-colors duration-500 ${
                index < currentIndex ? 'bg-blue-600' : 'bg-slate-300'
              }`} />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { Step, SubmissionData, STEPS } from './types';
import { StepIndicator } from './components/StepIndicator';
import { optimizeMetadata } from './services/geminiService';

// Icons using Lucide patterns (inline SVGs for simplicity)
const ChevronRight = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>;
const ChevronLeft = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>;
const Sparkles = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m12 3-1.912 5.813a2 2 0 0 1-1.275 1.275L3 12l5.813 1.912a2 2 0 0 1 1.275 1.275L12 21l1.912-5.813a2 2 0 0 1 1.275-1.275L21 12l-5.813-1.912a2 2 0 0 1-1.275-1.275L12 3Z"/><path d="M5 3v4"/><path d="M19 17v4"/><path d="M3 5h4"/><path d="M17 19h4"/></svg>;

const App: React.FC = () => {
  const [currentStep, setCurrentStep] = useState<Step>('SUBMITTER');
  const [data, setData] = useState<SubmissionData>({
    submitterName: '',
    department: '',
    email: '',
    title: '',
    description: '',
    recordingDate: '',
    category: 'Lecture',
    tags: [],
    aiSummary: '',
    suggestedTitle: '',
    copyrightHolder: 'The University of Tokyo',
    releaseScope: 'external',
    fileLink: ''
  });
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const nextStep = () => {
    const currentIndex = STEPS.indexOf(currentStep);
    if (currentIndex < STEPS.length - 1) {
      setCurrentStep(STEPS[currentIndex + 1]);
    }
  };

  const prevStep = () => {
    const currentIndex = STEPS.indexOf(currentStep);
    if (currentIndex > 0) {
      setCurrentStep(STEPS[currentIndex - 1]);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setData(prev => ({ ...prev, [name]: value }));
  };

  const runAIOptimization = async () => {
    if (!data.title || !data.description) {
      alert("Please fill in the title and description first.");
      return;
    }
    setIsOptimizing(true);
    try {
      const result = await optimizeMetadata(data.title, data.description);
      setData(prev => ({
        ...prev,
        suggestedTitle: result.suggestedTitle,
        aiSummary: result.summary,
        tags: result.tags
      }));
      nextStep();
    } catch (error) {
      console.error("AI Optimization failed", error);
      alert("AI optimization failed. Please try again or skip.");
    } finally {
      setIsOptimizing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitted(true);
  };

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center min-h-screen p-6">
        <div className="bg-white rounded-3xl shadow-2xl p-12 max-w-lg w-full text-center">
          <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
          </div>
          <h1 className="text-3xl font-bold text-slate-900 mb-4">送信完了</h1>
          <p className="text-slate-600 mb-8">
            動画登録申請を受け付けました。担当者が内容を確認の上、順次登録作業を行います。
          </p>
          <button 
            onClick={() => window.location.reload()}
            className="w-full bg-blue-600 text-white py-4 rounded-xl font-semibold hover:bg-blue-700 transition-colors"
          >
            新しく申請する
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-12 md:py-20">
      {/* Header */}
      <header className="mb-12 text-center">
        <div className="inline-flex items-center space-x-2 bg-blue-50 px-4 py-2 rounded-full mb-6">
          <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse" />
          <span className="text-blue-700 text-sm font-semibold tracking-wider uppercase">Portal v2.0</span>
        </div>
        <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 mb-4 tracking-tight">
          東大TV 動画登録申請
        </h1>
        <p className="text-slate-500 text-lg max-w-2xl mx-auto font-light">
          高品質な教育コンテンツを世界へ。Gemini AIがメタデータの最適化をサポートします。
        </p>
      </header>

      {/* Main Content */}
      <div className="max-w-4xl mx-auto">
        <StepIndicator currentStep={currentStep} />

        <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden transition-all duration-500">
          <form onSubmit={handleSubmit} className="p-8 md:p-12">

            {/* Step 1: Submitter Info */}
            {currentStep === 'SUBMITTER' && (
              <div className="space-y-8 animate-fadeIn">
                <div className="border-l-4 border-blue-600 pl-4 mb-8">
                  <h2 className="text-2xl font-bold text-slate-800">申請者情報</h2>
                  <p className="text-slate-500">ご連絡先の詳細を入力してください。</p>
                </div>
                <div className="grid md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">お名前 <span className="text-red-500">*</span></label>
                    <input 
                      required 
                      name="submitterName"
                      value={data.submitterName}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      placeholder="東京 太郎"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">所属部局 <span className="text-red-500">*</span></label>
                    <input 
                      required 
                      name="department"
                      value={data.department}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      placeholder="情報理工学系研究科"
                    />
                  </div>
                  <div className="md:col-span-2 space-y-2">
                    <label className="text-sm font-semibold text-slate-700">メールアドレス <span className="text-red-500">*</span></label>
                    <input 
                      required 
                      type="email"
                      name="email"
                      value={data.email}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      placeholder="taro@g.ecc.u-tokyo.ac.jp"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Step 2: Content Info */}
            {currentStep === 'CONTENT' && (
              <div className="space-y-8 animate-fadeIn">
                <div className="border-l-4 border-blue-600 pl-4 mb-8">
                  <h2 className="text-2xl font-bold text-slate-800">コンテンツ内容</h2>
                  <p className="text-slate-500">動画の基本情報を入力してください。</p>
                </div>
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">動画タイトル <span className="text-red-500">*</span></label>
                    <input 
                      required 
                      name="title"
                      value={data.title}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      placeholder="講義：量子コンピューティングの基礎"
                    />
                  </div>
                  <div className="grid md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-sm font-semibold text-slate-700">収録日</label>
                      <input 
                        type="date"
                        name="recordingDate"
                        value={data.recordingDate}
                        onChange={handleInputChange}
                        className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-semibold text-slate-700">カテゴリー</label>
                      <select 
                        name="category"
                        value={data.category}
                        onChange={handleInputChange}
                        className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all appearance-none bg-white"
                      >
                        <option>講義 (Lecture)</option>
                        <option>公開講座 (Public Course)</option>
                        <option>インタビュー (Interview)</option>
                        <option>紹介動画 (Introduction)</option>
                        <option>その他 (Other)</option>
                      </select>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">動画説明 <span className="text-red-500">*</span></label>
                    <textarea 
                      required 
                      name="description"
                      value={data.description}
                      onChange={handleInputChange}
                      rows={6}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none"
                      placeholder="この動画の内容について簡潔に説明してください。AIがこの情報を元に最適化を行います。"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Step 3: Optimize (AI) */}
            {currentStep === 'OPTIMIZE' && (
              <div className="space-y-8 animate-fadeIn">
                <div className="flex items-center justify-between border-l-4 border-amber-500 pl-4 mb-8">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-800">AI メタデータ最適化</h2>
                    <p className="text-slate-500">Gemini AIがあなたのコンテンツを魅力的に磨き上げます。</p>
                  </div>
                  <div className="hidden md:block">
                    <Sparkles />
                  </div>
                </div>

                {data.aiSummary ? (
                  <div className="space-y-6">
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200">
                      <h3 className="text-sm font-bold text-blue-600 mb-2 uppercase tracking-wide">提案されたタイトル</h3>
                      <p className="text-xl font-semibold text-slate-800">{data.suggestedTitle}</p>
                    </div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200">
                      <h3 className="text-sm font-bold text-blue-600 mb-2 uppercase tracking-wide">AI要約</h3>
                      <p className="text-slate-700 leading-relaxed">{data.aiSummary}</p>
                    </div>
                    <div>
                      <h3 className="text-sm font-bold text-slate-700 mb-3">生成されたタグ</h3>
                      <div className="flex flex-wrap gap-2">
                        {data.tags.map(tag => (
                          <span key={tag} className="px-3 py-1 bg-white border border-slate-300 rounded-full text-sm text-slate-600 font-medium">
                            #{tag}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <div className="mb-6 inline-block p-4 bg-blue-50 rounded-full">
                      <Sparkles />
                    </div>
                    <h3 className="text-xl font-bold text-slate-800 mb-2">準備はいいですか？</h3>
                    <p className="text-slate-500 mb-8 max-w-sm mx-auto">
                      「最適化を実行」をクリックすると、入力された情報を解析して、視聴者に響くタイトルと説明文を生成します。
                    </p>
                    <button 
                      type="button"
                      onClick={runAIOptimization}
                      disabled={isOptimizing}
                      className="inline-flex items-center px-8 py-4 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 disabled:opacity-50"
                    >
                      {isOptimizing ? (
                        <>
                          <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                          </svg>
                          最適化中...
                        </>
                      ) : (
                        <>
                          最適化を実行
                          <span className="ml-2"><Sparkles /></span>
                        </>
                      )}
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Step 4: Rights & Files */}
            {currentStep === 'RIGHTS' && (
              <div className="space-y-8 animate-fadeIn">
                <div className="border-l-4 border-blue-600 pl-4 mb-8">
                  <h2 className="text-2xl font-bold text-slate-800">権利・ファイル</h2>
                  <p className="text-slate-500">著作権と共有設定について確認してください。</p>
                </div>
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">著作権保持者</label>
                    <input 
                      name="copyrightHolder"
                      value={data.copyrightHolder}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                  </div>
                  <div className="space-y-4">
                    <label className="text-sm font-semibold text-slate-700 block">公開範囲</label>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      {([
                        { id: 'external', label: '外部公開', desc: 'YouTube/Todai TV' },
                        { id: 'internal', label: '学内限定', desc: 'SSO認証必須' },
                        { id: 'limited', label: '非公開', desc: 'アーカイブのみ' }
                      ] as const).map(scope => (
                        <label 
                          key={scope.id}
                          className={`flex flex-col p-4 border-2 rounded-2xl cursor-pointer transition-all ${
                            data.releaseScope === scope.id 
                              ? 'border-blue-600 bg-blue-50 text-blue-900' 
                              : 'border-slate-100 bg-slate-50 text-slate-500'
                          }`}
                        >
                          <input 
                            type="radio" 
                            name="releaseScope" 
                            value={scope.id} 
                            checked={data.releaseScope === scope.id}
                            onChange={() => setData(prev => ({ ...prev, releaseScope: scope.id }))}
                            className="sr-only"
                          />
                          <span className="font-bold mb-1">{scope.label}</span>
                          <span className="text-xs opacity-80">{scope.desc}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">動画ファイルへのリンク (Google Drive等)</label>
                    <input 
                      required 
                      type="url"
                      name="fileLink"
                      value={data.fileLink}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                      placeholder="https://drive.google.com/..."
                    />
                    <p className="text-[10px] text-slate-400">※ 動画ファイル自体のアップロードは現在開発中です。リンクを共有してください。</p>
                  </div>
                </div>
              </div>
            )}

            {/* Step 5: Confirm */}
            {currentStep === 'CONFIRM' && (
              <div className="space-y-8 animate-fadeIn">
                <div className="border-l-4 border-green-500 pl-4 mb-8">
                  <h2 className="text-2xl font-bold text-slate-800">最終確認</h2>
                  <p className="text-slate-500">入力内容に間違いがないかご確認ください。</p>
                </div>

                <div className="grid grid-cols-1 gap-6 bg-slate-50 p-6 md:p-8 rounded-3xl border border-slate-200">
                  <div className="grid md:grid-cols-3 border-b border-slate-200 pb-4">
                    <span className="text-slate-400 text-sm font-medium">申請者</span>
                    <span className="md:col-span-2 text-slate-800 font-bold">{data.submitterName} ({data.department})</span>
                  </div>
                  <div className="grid md:grid-cols-3 border-b border-slate-200 pb-4">
                    <span className="text-slate-400 text-sm font-medium">タイトル</span>
                    <span className="md:col-span-2 text-slate-800 font-bold">{data.suggestedTitle || data.title}</span>
                  </div>
                  <div className="grid md:grid-cols-3 border-b border-slate-200 pb-4">
                    <span className="text-slate-400 text-sm font-medium">公開範囲</span>
                    <span className="md:col-span-2">
                      <span className="px-3 py-1 bg-blue-100 text-blue-700 text-xs font-bold rounded-full uppercase">
                        {data.releaseScope}
                      </span>
                    </span>
                  </div>
                  <div className="space-y-2">
                    <span className="text-slate-400 text-sm font-medium">動画要約</span>
                    <p className="text-slate-700 text-sm leading-relaxed italic bg-white p-4 rounded-xl border border-slate-200">
                      {data.aiSummary || data.description}
                    </p>
                  </div>
                </div>

                <div className="bg-amber-50 p-4 rounded-xl flex items-start space-x-3 text-amber-700">
                  <div className="mt-0.5"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg></div>
                  <p className="text-xs leading-relaxed">
                    送信ボタンを押すと、入力したメールアドレスに確認メールが届きます。登録には通常3-5営業日かかります。
                  </p>
                </div>
              </div>
            )}

            {/* Navigation Controls */}
            <div className="mt-12 flex flex-col md:flex-row items-center justify-between gap-4 border-t border-slate-100 pt-8">
              <div className="w-full md:w-auto">
                {currentStep !== 'SUBMITTER' && (
                  <button 
                    type="button" 
                    onClick={prevStep}
